<script>(function(){const body=document.getElementById('saleLines'),tpl=document.getElementById('saleLineTemplate'),discount=document.getElementById('saleDiscount'),categoryChoice=document.getElementById('productCategory'),customField=document.getElementById('customCategoryField'),customCategory=document.getElementById('customCategory');let index=0;function total(){let sum=0;body.querySelectorAll('tr').forEach(row=>{const q=parseFloat(row.querySelector('[data-quantity]').value)||0,p=parseFloat(row.querySelector('[data-price]').value)||0,v=q*p;row.querySelector('[data-line-total]').textContent='UGX '+Math.round(v).toLocaleString();sum+=v});sum=Math.max(0,sum-(parseFloat(discount.value)||0));document.getElementById('invoiceTotal').textContent='UGX '+Math.round(sum).toLocaleString()}function add(){const row=tpl.content.firstElementChild.cloneNode(true),i=index++,product=row.querySelector('[data-product]'),category=row.querySelector('[data-category]'),description=row.querySelector('[data-description]'),unit=row.querySelector('[data-unit]'),qty=row.querySelector('[data-quantity]'),price=row.querySelector('[data-price]');product.name=`lines[${i}][product_id]`;category.name=`lines[${i}][category]`;description.name=`lines[${i}][description]`;unit.name=`lines[${i}][unit]`;qty.name=`lines[${i}][quantity]`;price.name=`lines[${i}][unit_price]`;product.onchange=()=>{const option=product.selectedOptions[0],listed=!!product.value;price.value=option?.dataset.price||'';unit.value=option?.dataset.unit||'';category.value=option?.dataset.category||'';category.readOnly=listed;description.disabled=listed;unit.readOnly=listed;description.placeholder=listed?'Uses catalogue name':'Type product if unlisted';total()};qty.oninput=price.oninput=total;row.querySelector('[data-remove]').onclick=()=>{row.remove();total()};body.appendChild(row)}document.getElementById('addSaleLine').onclick=add;discount.oninput=total;categoryChoice.onchange=()=>{const custom=categoryChoice.value==='custom';customField.hidden=!custom;customCategory.required=custom;if(custom)customCategory.focus()};categoryChoice.onchange();add()})();</script>
